/* Standalone studio design proposals. Demo state is separate from the workbench. */
const sections = ['基础信息', '人设与规则', 'Skills 与能力', '记忆', '知识库', '自进化', '运行轨迹'];
const paths = { layers:'M12 3 2 8l10 5 10-5-10-5Zm-10 9 10 5 10-5M2 16l10 5 10-5', grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z', code:'m8 6-6 6 6 6m8-12 6 6-6 6M14 3l-4 18', shield:'M12 3 3 7v5c0 5 9 9 9 9s9-4 9-9V7l-9-4Zm-4 9 3 3 5-6', book:'M4 3h14v18H4zM8 7h6M8 11h6', spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7Z', clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 4v5l4 2', folder:'M3 6h7l2 2h9v12H3z', chevron:'m9 5 7 7-7 7', plus:'M12 5v14M5 12h14', settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1 1-3Z', sun:'M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10ZM12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2', panel:'M3 4h18v16H3zM8 4v16', check:'m4 12 5 5L20 6', arrow:'M5 12h14m-6-6 6 6-6 6', x:'m6 6 12 12M6 18 18 6', person:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM4 21v-3c0-5 16-5 16 0v3', link:'m9 15 6-6M8 13l-2 2a3 3 0 0 0 4 4l3-3M11 8l3-3a3 3 0 0 1 4 4l-2 2' };
const icon = (name, size=18) => `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name] || paths.grid}"/></svg>`;
const esc = value => String(value).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const variant = ['a','b','c'].includes(new URLSearchParams(location.search).get('variant')) ? new URLSearchParams(location.search).get('variant') : 'a';
const definitions = [
  {id:'coding',name:'编码智能体',key:'lg-coding-agent',description:'理解项目，完成代码开发、修改与检查。',type:'内置智能体',symbol:'code',role:'你是一位严谨的工程师。先了解项目规则，再进行修改；用验证结果说明完成情况。',duties:'代码开发、问题定位、重构与检查'},
  {id:'examine',name:'审查智能体',key:'lg-examine',description:'独立核对交付结果，让每一个结论都有证据。',type:'内置智能体',symbol:'shield',role:'你是一位独立审查者。围绕验收标准核对证据，主动寻找反例；证据不足时明确说明。',duties:'验收审查、证据核对、多轮复核'},
  {id:'research',name:'行业研究助手',key:'industry-research',description:'整理行业资料，比较方案，给出可追溯的研究结论。',type:'自建智能体 · 示例',symbol:'book',role:'你是一位研究助手。区分事实与推断，为结论标注来源和日期。',duties:'行业研究、资料整理、方案比较'}
];
const storageKey = 'lg-studio-designs-v1';
let stored = {};
try { stored = JSON.parse(localStorage.getItem(storageKey) || '{}'); } catch { stored = {}; }
if (!stored || typeof stored !== 'object') stored = {};
const agents = definitions.map(a=>({...a,...(stored.agents?.[a.id] || {}),version:Number(stored.agents?.[a.id]?.version)||3,dirty:false}));
let state = {agent:0,section:0,scope:'通用',collapsed:false,chat:false};
document.documentElement.dataset.theme = stored.theme === 'light' ? 'light' : 'dark';
const root = document.getElementById('studio');
const detail = document.getElementById('detail');
const current = () => agents[state.agent];
const badge = (text, cls='') => `<span class="tag ${cls}">${text}</span>`;
const button = (label, action, cls='btn', attrs='') => `<button type="button" class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const scopePicker = () => `<div class="scope-picker"><select aria-label="查看作用范围" data-scope>${['通用','客户服务工作台','供应链调研'].map(x=>`<option ${x===state.scope?'selected':''}>${x}</option>`).join('')}</select></div>`;
const field = (label, key, large=false) => `<label class="form-field"><span>${label}</span>${large?`<textarea data-field="${key}" class="large">${esc(current()[key] || '')}</textarea>`:`<input data-field="${key}" value="${esc(current()[key] || '')}">`}</label>`;
const toggle = (key, value=true) => `<button class="switch" role="switch" aria-label="启用${esc(key)}" aria-checked="${current()[key] ?? value}" data-toggle="${esc(key)}"></button>`;
function toast(text) { const el=document.getElementById('feedback');el.textContent=text;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),3200); }
function persist() { try { const previous=JSON.parse(localStorage.getItem(storageKey)||'{}');const a=current();localStorage.setItem(storageKey,JSON.stringify({theme:document.documentElement.dataset.theme,agents:{...previous.agents,[a.id]:Object.fromEntries(Object.entries(a).filter(([k])=>k!=='dirty'))}}));return true; } catch { toast('浏览器未能保存，请保持此页面打开。');return false; } }
function save() { const a=current();if(!a.dirty){toast('当前没有待保存的修改');return;}a.version++;a.dirty=false;if(persist()){render();toast(`已保存为 v${a.version}，仅新会话使用。已有会话继续使用原版本。`);} }
function sidebar() { return `<aside class="global-sidebar"><div class="logo"><span class="logo-mark">${icon('layers',24)}</span><div class="logo-text"><b>LG Workbench</b><small>YOUR AGENT WORKSPACE</small></div>${button(icon('panel',16),'collapse','icon-btn','aria-label="收起左侧导航"')}</div>${button(icon('panel'),'collapse','icon-btn expand-only','aria-label="展开左侧导航"')}<a class="new-project" href="../index.html">${icon('plus')}<span>新建项目</span></a><div class="side-caption">项目空间 <span>03</span></div><div class="project-list">${[['客户服务工作台',['完善工单导出功能','导出结果 · 独立验收']],['供应链调研',['调研结论 · 证据核对']],['新产品构思',[]]].map(([name,sessions])=>`<div class="project-group"><a href="../index.html" class="project-title">${icon('chevron',13)}<b>${name}</b><span class="plus">+</span></a>${sessions.map(x=>`<a href="../index.html" class="project-session"><i class="dot"></i>${x}<small>${x.includes('导出功能')?'编码':'审查'}</small></a>`).join('')}</div>`).join('')}</div><div class="agent-dock"><div class="dock-head">智能体 <span>03</span></div>${agents.map((a,i)=>`<button class="agent-item ${i===state.agent?'active':''}" data-agent="${i}" title="${esc(a.name)}"><span class="avatar ${i===1?'review':''}">${icon(a.symbol)}</span><span class="agent-caption"><b>${esc(a.name)}</b><small>${i===2?'自建 · 设计示例':a.duties.split('、').slice(0,2).join('与')}</small></span></button>`).join('')}</div><div class="side-footer"><div class="connection"><i class="dot"></i>本地工作台 · 设计演示</div><div class="settings-row"><a href="../index.html">${icon('settings',17)}<span>全局设置</span></a>${button(icon('sun',17),'theme','icon-btn','aria-label="切换明暗主题"')}</div></div></aside>`; }
function header() { return `<header class="topbar"><div class="crumb">${icon('layers',17)}<span>智能体工作室</span><span>/</span><b>${esc(current().name)}</b></div><div class="top-actions"><div class="versions">${['a','b','c'].map((v,i)=>`<a class="${variant===v?'active':''}" href="studio.html?variant=${v}">${['A 目录','B 总览','C 分栏'][i]}</a>`).join('')}</div><a class="text-link" href="index.html">三版对比</a><a class="text-link" href="../index.html">返回工作台 ${icon('arrow',14)}</a></div></header>`; }
function hero() { const a=current();return `<div class="hero"><span class="avatar ${state.agent===1?'review':''}">${icon(a.symbol,28)}</span><div class="hero-text"><div class="flex"><h1>${esc(a.name)}</h1>${badge(a.type)}${badge('v'+a.version)}</div><p>${esc(a.description)}</p></div><div class="hero-actions"><span class="save-state">${a.dirty?'有未保存修改':'配置已保存'}</span>${button('开始会话','start','btn')}${button('保存修改','save','btn primary')}</div></div><div class="persist-note">${icon('clock',14)}<span>修改仅对新会话生效。已有会话、审查轮次和恢复任务继续使用原配置。</span></div>`; }
function nav(cls='directory') { const icons=['person','book','grid','layers','folder','spark','clock'];return `<nav class="${cls}" aria-label="工作室区域">${sections.map((s,i)=>`<button class="${state.section===i?'active':''}" data-section="${i}" aria-current="${state.section===i?'page':'false'}">${icon(icons[i],17)}<span>${s}</span>${cls==='directory'?`<small class="nav-number">0${i+1}</small>`:''}</button>`).join('')}${cls==='directory'?'<div class="directory-foot">模型与运行参数<br>统一使用全局设置</div>':''}</nav>`; }
const sectionHeader = (title,desc,eyebrow='AGENT STUDIO') => `<div class="section-header"><div><span class="eyebrow">${eyebrow}</span><h2>${title}</h2><p>${desc}</p></div>${badge(state.section<3?'智能体配置':state.scope)}</div>`;
function scopeLine() { return `<div class="scope-line"><span>查看作用范围</span>${scopePicker()}<span class="muted">项目资料只在对应项目使用</span></div>`; }
function basics() { const a=current();const form=`${field('智能体名称','name')}${field('简短描述','description')}<div class="two-col">${field('主要职责','duties')}<label class="form-field"><span>智能体标识</span><input value="${esc(a.key)}" readonly><small class="field-help">用于区分智能体，创建后保持不变。</small></label></div>`;
 if(variant==='b')return `<div class="overview-grid"><section class="panel"><div class="panel-head"><h3>定义它的工作</h3>${badge('身份')}</div>${form}</section><div class="overview-right"><section class="panel"><div class="panel-head"><h3>能力概览</h3>${button('管理','section-2','text-link')}</div><div class="capability-grid">${[['code','项目读写'],['shield','执行检查'],['book','项目规则'],['link','MCP 连接']].map(([i,t])=>`<button class="capability-tile" data-action="section-2">${icon(i)}<b>${t}</b><span>已启用</span></button>`).join('')}</div></section><section class="panel"><div class="panel-head"><h3>持续改进</h3>${badge('1 条建议','amber')}</div><p class="muted">多次遗漏空数据检查，建议补充交付前核对清单。</p>${button('查看证据与建议 '+icon('arrow',14),'section-5','text-link')}</section></div><section class="panel wide"><div class="panel-head"><h3>最近运行</h3>${button('全部记录','section-6','text-link')}</div><div class="mini-trace"><span><i class="dot"></i> 完善工单导出功能</span><span class="muted">客户服务工作台 · 今天 10:42</span>${badge('已完成')}</div></section></div>`;
 return `${sectionHeader('让智能体知道自己负责什么','名称、描述和职责，会出现在智能体列表与新会话中。','01 / IDENTITY')}<div class="avatar-editor"><span class="avatar ${state.agent===1?'review':''}">${icon(a.symbol,26)}</span><div><b>${a.type}</b><p class="muted">${esc(a.key)} · 每个智能体拥有独立配置</p></div></div>${form}<div class="soft-line"></div><div class="identity-grid"><div><span>配置归属</span><b>当前智能体</b></div><div><span>生效范围</span><b>使用它的新会话</b></div></div><div class="notice-box">模型、重试、上下文与运行参数统一使用全局设置。工作室只定义这个智能体的职责与能力。</div>`;
}
function rules() { return `${sectionHeader('人设与规则','通用规则跟随智能体；项目约定只在当前项目读取。','02 / INSTRUCTIONS')}${field('通用人设与工作原则','role',true)}<div class="chips">${['先读规则','用事实说明','完成后验证'].map(x=>`<span class="chip">${x}</span>`).join('')}</div><div class="soft-line"></div>${scopeLine()}<h3>项目约定</h3>${state.scope==='通用'?'<div class="empty-data">选择一个项目，查看它的 AGENTS.md 和补充约定。</div>':`<div class="list-row">${icon('book')}<div class="row-main"><b>AGENTS.md</b><p>${esc(state.scope)} · 项目内规则 · 只在此项目使用</p></div>${button('查看','project-rules','text-link')}</div><p class="rule-note">项目约定可以细化工作方式，不能放宽工具边界或覆盖平台审批规则。</p>`}`; }
function capabilities() { return `${sectionHeader('组合它需要的能力','从已登记的 Skills、工具与 MCP 连接中选择。','03 / CAPABILITIES')}<div class="tiny-title">SKILLS</div>${[['代码检查','定位问题、补齐检查并说明结果'],['技术写作','整理实现说明与交付文档']].map(([k,d])=>`<div class="list-row"><span class="small-icon">${icon('code')}</span><div class="row-main"><b>${k}</b><p>${d}</p></div>${toggle(k)}</div>`).join('')}<div class="tiny-title">工具</div>${[['项目文件','读取与修改已关联的项目目录'],['命令执行','遵循全局审批与项目资源约束']].map(([k,d])=>`<div class="list-row"><span class="small-icon">${icon('folder')}</span><div class="row-main"><b>${k}</b><p>${d}</p></div>${toggle(k)}</div>`).join('')}<div class="tiny-title">MCP</div><div class="list-row"><span class="small-icon">${icon('link')}</span><div class="row-main"><b>文档检索</b><p>复用全局连接 · 凭据不存入智能体</p></div>${toggle('文档检索',false)}</div><div class="notice-box">启用能力不会新增访问权限。项目目录、资料和外部资源需要按项目绑定。</div>${scopeLine()}${state.scope!=='通用'?`<div class="list-row"><div class="row-main"><b>${esc(state.scope)}的资源绑定</b><p>项目目录与文档集合 · 仅供此项目的新会话使用</p></div>${button('查看','resources','text-link')}</div>`:''}`; }
function memory() { const title=state.scope==='通用'?'交付说明应附检查结果':state.scope==='客户服务工作台'?'导出文件需要兼容中文 Excel':'供应商结论需要保留资料日期';return `${sectionHeader('记住有用的经验','智能体通用经验和项目记忆分开保存。','04 / MEMORY')}${scopeLine()}<div class="list-row"><span class="small-icon">${icon('layers')}</span><div class="row-main"><b>${title}</b><p>${state.scope==='通用'?'通用经验 · 从历史运行整理':esc(state.scope)+' · 项目记忆'} · 有来源记录</p></div>${button('查看来源','memory-source','text-link')}</div><div class="notice-box">记忆不是执行指令。确认后的新版本供新会话使用；已有会话不会因记忆更新而改变。</div><div class="soft-line"></div><h3>使用边界</h3><p class="muted">跨项目只复用通用经验。客户资料、项目结论与私有文件内容保留在各自项目内。</p>`; }
function knowledge() { return `${sectionHeader('提供可靠的参考资料','公共知识与项目专有资料分开，保留来源和版本。','05 / KNOWLEDGE')}${scopeLine()}${(state.scope==='通用'?[['工程交付规范.md','通用知识 · v2'],['代码检查清单.md','通用知识 · v1']]:state.scope==='客户服务工作台'?[['工单接口约定.md','客户服务工作台 · v3'],['导出验收标准.md','客户服务工作台 · v1']]:[['供应商资料目录.md','供应链调研 · v1']]).map(([n,d])=>`<div class="list-row"><span class="small-icon">${icon('book')}</span><div class="row-main"><b>${n}</b><p>${d} · 已绑定</p></div>${button('查看','knowledge-detail','text-link',`data-name="${n}"`)}</div>`).join('')}<div class="notice-box">绑定资料后，新会话读取对应版本。跨项目切换不会把上一项目的资料带过来。</div>`; }
function evolution() { const applied=current().evolved;return `${sectionHeader('从实际运行中发现改进点','先看证据，再验证改动，确认后用于新会话。','06 / EVOLUTION')}<div class="steps"><span>发现问题</span><i class="line"></i><span>形成建议</span><i class="line"></i><span>验证</span><i class="line"></i><span>确认应用</span></div><div class="evolution-card"><div class="flex">${badge(applied?'已应用':'待确认',applied?'':'amber')}<span class="muted">能力改进 · 交付检查</span></div><h3>把空数据检查加入交付前清单</h3><p>最近 3 次相关任务中，有 2 次在复核时才补上空数据检查。建议在通用检查流程里增加一项提醒。</p><div class="statline"><span>来源：3 条运行记录</span><span>验证：2 组历史案例通过</span></div><div class="actions">${button('查看证据与改动','evolution-detail','btn')}${button(applied?'已应用到新版本':'确认应用到新会话','evolution-apply',applied?'btn':'btn primary',applied?'disabled':'')}</div></div><div class="notice-box">演示建议不自动修改代码、工具权限或运行中的会话。项目特有经验先留在项目内，通用改动需确认。</div>${scopeLine()}<p class="muted">当前查看：${esc(state.scope)}。真实系统按运行证据归属区分通用改进与项目改进。</p>`; }
function trace() { const rows=[['今天 10:42','客户服务工作台','完善工单导出功能','已完成'],['昨天 16:20','客户服务工作台','检查接口边界','已停止'],['昨天 09:30','供应链调研','整理资料结构','已完成']].filter(r=>state.scope==='通用'||r[1]===state.scope);return `${sectionHeader('只保留关键运行记录','看清做过什么，需要细节时打开原会话。','07 / ACTIVITY')}${scopeLine()}<table class="trace-table"><thead><tr><th>时间 / 项目</th><th>任务</th><th>状态</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r[0]}<small>${r[1]}</small></td><td>${r[2]}</td><td>${badge(r[3])}</td><td>${button('查看','trace-detail','text-link',`data-name="${r[2]}"`)}</td></tr>`).join('')}</tbody></table><p class="rule-note">轨迹只展示当前智能体的记录。示例数据用于比较布局，不代表真实执行。</p>`; }
function rail() {return `<aside class="context-rail"><div class="scope-block"><span class="eyebrow">WORKING SCOPE</span><h3>作用范围</h3>${scopePicker()}<p>切换项目只改变资料范围，不会创建另一个智能体。</p></div><div class="scope-node active"><b>智能体通用</b><span>身份、人设与能力定义<br>通用经验与知识</span></div><div class="scope-node"><b>${state.scope==='通用'?'项目内使用':esc(state.scope)}</b><span>项目规则与目录<br>项目记忆与专有资料</span></div><div class="scope-block"><h3>生效规则</h3><p>保存为新版本。<br>仅新会话采用修改。</p><p>原会话、已有审查轮次与恢复任务保持原配置。</p></div><div class="scope-block"><h3>统一运行配置</h3><p>模型、上下文、重试和审批规则使用全局设置。</p></div></aside>`; }
function chat() { return `<div class="start-page"><span class="avatar">${icon(current().symbol,30)}</span><h2>让${esc(current().name)}开始工作</h2><p>新会话将使用已保存的 v${current().version} 配置。</p><label class="form-field"><span>项目</span><select aria-label="新会话项目"><option>客户服务工作台</option><option>供应链调研</option></select></label><label class="form-field"><span>这次想完成什么？</span><textarea id="demo-task" class="large" placeholder="描述任务、要求和期望结果…"></textarea></label><div class="hero-actions">${button('返回工作室','back','btn')}${button('发送消息','send','btn primary')}</div><p class="field-help">设计演示，不会调用模型或修改本地文件。</p></div>`; }
function render() { root.className=`variant-${variant}${state.collapsed?' collapsed':''}`;const content=[basics,rules,capabilities,memory,knowledge,evolution,trace][state.section]();root.innerHTML=`${sidebar()}${header()}<main class="workspace">${state.chat?chat():`<div class="page">${hero()}${variant==='b'?`${nav('tab-nav')}<div class="main-form">${content}</div>`:variant==='c'?`<div class="workbench-body">${nav()}<section class="document-page">${content}</section>${rail()}</div>`:`<div class="directory-body">${nav()}<section class="main-form">${content}</section></div>`}</div>`}</main><footer class="bottom-bar"><span>2.0 智能体工作室 · ${ {a:'A 目录式',b:'B 总览式',c:'C 分栏式'}[variant]}</span><span>设计提案 · 演示数据 · 未连接模型</span></footer>`; }
function modal(title,body,actions='') {detail.innerHTML=`<div class="dialog-head"><h2 id="detail-title">${title}</h2>${button(icon('x'),'close','icon-btn','aria-label="关闭详情"')}</div><div class="dialog-copy">${body}</div><div class="dialog-actions">${actions || button('知道了','close','btn primary')}</div>`;detail.showModal();}
document.addEventListener('input',e=>{if(e.target.dataset.field){current()[e.target.dataset.field]=e.target.value;current().dirty=true;document.querySelector('.save-state').textContent='有未保存修改';}});
document.addEventListener('change',e=>{if(e.target.hasAttribute('data-scope')){state.scope=e.target.value;render();}});
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;
 if(el.dataset.section!==undefined){state.section=Number(el.dataset.section);render();return;}
 if(el.dataset.agent!==undefined){state.agent=Number(el.dataset.agent);state.chat=false;render();return;}
 if(el.dataset.toggle){const key=el.dataset.toggle;current()[key]=el.getAttribute('aria-checked')!=='true';current().dirty=true;render();return;}
 const action=el.dataset.action;
 if(action?.startsWith('section-')){state.section=Number(action.split('-')[1]);render();return;}
 if(action==='theme'){document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';try{const snapshot=JSON.parse(localStorage.getItem(storageKey)||'{}');localStorage.setItem(storageKey,JSON.stringify({...snapshot,theme:document.documentElement.dataset.theme}));}catch{toast('主题已切换，本次无法保存浏览器偏好');}return;}
 if(action==='collapse'){state.collapsed=!state.collapsed;render();}
 if(action==='save')save();
 if(action==='start'){if(current().dirty){modal('先保存修改','<p>新会话使用已保存的配置。保存后再开始，已有会话保持原版本。</p>',button('继续编辑','close','btn')+button('保存并开始','save-start','btn primary'));}else{state.chat=true;render();}}
 if(action==='save-start'){save();detail.close();state.chat=true;render();}
 if(action==='back'){state.chat=false;render();}
 if(action==='send'){const value=document.getElementById('demo-task').value.trim();if(!value){toast('先填写这次要完成的任务');return;}modal('新会话已准备好',`<p>${esc(value)}</p><div class="notice-box">${esc(current().name)} · 配置 v${current().version}<br>这里只演示新会话绑定配置，没有启动真实任务。</div>`);}
 if(action==='close')detail.close();
 if(action==='evolution-detail')modal('交付检查 · 改进证据','<p>样例：3 次相关运行中，2 次在复核时补做空数据检查。</p><div class="change-line"><b>建议改动</b><p>交付前检查：正常数据、空数据、编码与筛选条件。</p></div><div class="change-line"><b>验证结果</b><p>2 组历史案例通过；未新增工具或放宽审批范围。</p></div><p>确认后生成新配置版本，已有会话不变。</p>');
 if(action==='evolution-apply')modal('确认应用这项改进','<p>把空数据检查加入通用交付清单。新版本只用于新会话。</p>',button('取消','close','btn')+button('确认应用','apply-confirm','btn primary'));
 if(action==='apply-confirm'){current().evolved=true;current().dirty=true;save();detail.close();}
 if(action==='project-rules')modal('项目规则 · '+esc(state.scope),'<p>AGENTS.md · 项目规则示例</p><div class="detail-doc">修改前阅读接口约定；交付附检查结果；不把本项目资料带入其他项目。</div>');
 if(action==='resources')modal('项目资源绑定',`<p>${esc(state.scope)} · 示例</p><div class="detail-doc">项目目录：D:/workspace/${state.scope==='客户服务工作台'?'service-desk':'supply-research'}<br>文档检索：当前项目的文档集合</div><p>连接凭据复用全局设置，不复制到智能体内。</p>`);
 if(action==='memory-source')modal('记忆来源',`<p>样例来源：${state.scope==='供应链调研'?'调研结论 → 证据核对':'完善工单导出功能 → 交付复核'}。</p><p>从运行记录整理，保留项目归属。确认后供新会话使用，不改写已有会话。</p>`);
 if(action==='knowledge-detail')modal(esc(el.dataset.name),'<p>资料预览示例：版本固定，保留来源。真实系统按当前项目绑定读取资料。</p>');
 if(action==='trace-detail')modal('原会话 · '+esc(el.dataset.name),`<p>${esc(current().name)} · 独立运行记录示例</p><div class="detail-doc">任务已结束，交付记录保留。此入口在正式工作室中返回对应会话。</div>`);
});
render();
